 for i,s in enumerate(d['sources'],1):sources.append('<details class="source"><summary>'+html.escape(s['name'])+'</summary><p><a href="'+s['path']+'">完整UTF-8源码</a> · SHA256 <code>'+s['sha256']+'</code></p><pre id="source-code-'+str(i)+'">'+html.escape(s['text'])+'</pre></details>')
 page=TEMPLATE.replace('__STYLE__',style).replace('__SOURCES__','\n'.join(sources)).replace('__DATA__',json.dumps({k:v for k,v in d.items()if k!='sources'},ensure_ascii=False,separators=(',',':')).replace('<','\\u003c'))
 q=Inspect();q.feed(page);assert len(q.ids)==len(set(q.ids))
 for i,s in enumerate(d['sources'],1):assert q.pre['source-code-'+str(i)]==s['text']
 missing=[u for u in q.links if not u.startswith(('#','http:','https:'))and u not in('verification.json','package-receipt.json')and not(OUT/u.split('#')[0]).exists()];assert not missing,missing
 js=re.findall(r'<script>(.*?)</script>',page,re.S)[0];node=shutil.which('node');assert node;r=subprocess.run([node,'--check'],input=js,text=True,capture_output=True);assert r.returncode==0,r.stderr
 if not a.check_only:(OUT/'index.html').write_text(page)
 print(json.dumps(dict(status='static_checks_passed'if a.check_only else'built_static_checks_passed',HTML_created=not a.check_only,HTML_sha256=hashlib.sha256(page.encode()).hexdigest(),HTML_bytes=len(page.encode()),source_UTF8_exact=True,source_modules=2,unique_DOM_ids=len(q.ids),local_links=len(q.links),missing_links=missing,JS_syntax_passed=True,native_routes=2,native_points=sum(len(r['points'])for r in d['routes']),embedded_events=sum(len(r['events'])for r in d['routes']),selected_accesses=7,acceptance_dimensions=10,source_CPU_cases=0,Native_runs=0)))
